"""Render the frozen normal-application return measurements."""
from pathlib import Path
import csv,json
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/nc/application-return-2026-11-17'
r=json.loads((OUT/'results.json').read_text(encoding='utf-8'))
rows=[]
for q in r['rows']:
 rows.append(dict(profile=q['profile'],font=q['font'],application=q['application'],total_ms=q['total_ticks']/2000,font_ms=q['font_ticks']/2000,gfx_reload_ms=q['gfx_load_ticks']/2000,font_restored=bool(q['font_pending'])))
with (OUT/'summary.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
lines=['# Возврат в NC из обычных программ, 17.11.2026','',
'Emu80, модель 8080/MX2, CPU/PIT 2 МГц. Это эмуляторные значения, не замеры реального оборудования. Обе версии NC и все программы взяты из одного зафиксированного каталога `build/`; в нём сборка до добавления MAINREGISTER. На H: 32 записи, чтобы обычный NC мог работать с Packed6K. Эти числа нельзя напрямую сопоставлять с предыдущим отчётом на 128 записях.','',
'Ввод и запуск — через штатную командную строку и клавиатуру. Начало измерения — после получения завершающей клавиши, на инструкции выхода приложения. Конец — вход BIOS getch2 после восстановления и полного рисования NC. Ожидание пользователя, набор команды, запуск программы и временная замена шрифта перед её запуском в это время не включены. Время взято из тактов CPU эмулятора.','',
'TINY: небольшой MAIN-образ; BIG: управляемая MAIN-область до 6000h, вытесняет GFX; ALL: EXCLUSIVE до 8C00h, требует восстановления нижнего пререндера; BNK: обычная BANK-программа; EDIT: настоящий редактор из этой сборки, выход его штатной клавишей. Тестовые программы возвращаются через RET, EDIT — через системный возврат. Все исходники и контейнеры тестов лежат в `fixtures/`.','',
'«Шрифт» включает весь biosRestoreFont: проверку сохранённой конфигурации, а при необходимости загрузку FONT и его работу до возврата. Около 2,32 мс при отсутствии восстановления — накладные расходы проверки. «GFX» — ncBankLoadGraphics → ncBankGraphicsReady, только если DLL была вытеснена. Шрифт и GFX входят в общее время, а не добавляются к нему.','',
'| Профиль | Шрифт | Программа | Всего, мс | Шрифт, мс | GFX, мс |','|---|---|---|---:|---:|---:|']
for q in rows:lines.append(f"| {q['profile']} | {q['font']} | {q['application']} | {q['total_ms']:.2f} | {q['font_ms']:.2f} | {q['gfx_reload_ms']:.2f} |")
lines+=['','Fast12K проверяется только с BANK: текущий обычный NC не помещается ниже его MAIN-предела 6400h. После каждого возврата проверен идентификатор работающего шрифтового движка.','',
'## Вариант с MAIN-интерфейсом и банковыми данными','',
'Это предложение, не реализованный третий профиль. Оставить в MAIN обработку стрелок/редактора команды, рисование, цвета и готовое представление видимых строк; перенести в EXEC каталоги, кэш, сортировку, загрузку конфигурации и получение данных DOS. Передавать подготовленные окна записей пакетами, с упреждающей загрузкой соседних строк; обычная стрелка внутри окна не должна вызывать EXEC.','',
'Две полные панели по 255 записей × 16 байт потребуют 8160 байт. Текущий код обычного NC занимает примерно 21 КБ, поэтому вместе с переменными, тулбарами и полными списками он не поместится ниже 6400h при Fast12K. Нужно либо оставить в MAIN лишь видимые строки (примерно 1–2 КБ с запасом), либо дополнительно вынести несколько КБ кода. Нынешние Radix/snapshot-буферы также нужно убрать из фиксированного MAIN-хвоста. Снимки диалогов могут храниться в EXEC с пакетным сохранением/восстановлением; копировщики и горячий путь текста остаются в MAIN.','',
'Штатная регистрация MAIN-буферов добавлена отдельно после этой серии: MEMORY/MAINREGISTER, обычное владение приложением/модулем, проверка загрузчиком и автоматическое освобождение. Гибридный профиль пока не реализован.','',
'Артефакты: `results.json`, `summary.csv`, исходники стенда в `scripts/emu80/benchmark-nc-return.py`. SHA-256 образа и основных бинарников сохранены в results.json.']
(OUT/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(OUT/'report.md')
